import{_ as t,o as a,c as e,ag as p}from"./chunks/framework.DzGOF12C.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/철학 상담/북한 철학·문학 자료 분석 과제.md","filePath":"philosophy/철학 상담/북한 철학·문학 자료 분석 과제.md"}'),r={name:"philosophy/철학 상담/북한 철학·문학 자료 분석 과제.md"};function _(u,o,l,n,s,i){return a(),e("div",null,[...o[0]||(o[0]=[p('<h2 id="_1-이념적-배경-분석-틀-을-먼저-구축하기-위해-가장-추천" tabindex="-1">1. 이념적 배경(분석 틀)을 먼저 구축하기 위해 (가장 추천) <a class="header-anchor" href="#_1-이념적-배경-분석-틀-을-먼저-구축하기-위해-가장-추천" aria-label="Permalink to &quot;1. 이념적 배경(분석 틀)을 먼저 구축하기 위해 (가장 추천)&quot;">​</a></h2><p>북한의 문학 작품을 올바르게 해석하기 위해, 그 바탕에 깔린 사상적 가이드라인을 학술지를 통해 먼저 파악했다는 논리입니다.</p><ul><li><strong>작성 예시:</strong><blockquote><p>&quot;북한의 문학은 체제 이념과 사상적 기반을 대중에게 전달하는 프로파간다(선전·선동) 수단으로 기능한다는 점에 주목했다. 따라서 문학 소설을 읽기 전에, 그들의 사상적 뿌리가 학술적으로 어떻게 정립되어 있는지 《김일성종합대학학보 -철학-》을 통해 먼저 파악하고자 했다. 철학적 배경이라는 &#39;분석의 렌즈&#39;를 먼저 확보해야만, 이후에 읽은 소설 속 인물들의 갈등과 선택을 단순한 스토리가 아닌 &#39;이념의 실천 과정&#39;으로 깊이 있게 분석할 수 있을 것이라 판단했기 때문이다.&quot;</p></blockquote></li></ul><h2 id="본론-1-《김일성종합대학학보-철학-》-분석-—-이념의-언어적-가공과-두-개의-철학-담론" tabindex="-1">본론 1: 《김일성종합대학학보 -철학-》 분석 — 이념의 언어적 가공과 두 개의 철학 담론 <a class="header-anchor" href="#본론-1-《김일성종합대학학보-철학-》-분석-—-이념의-언어적-가공과-두-개의-철학-담론" aria-label="Permalink to &quot;본론 1: 《김일성종합대학학보 -철학-》 분석 — 이념의 언어적 가공과 두 개의 철학 담론&quot;">​</a></h2><p>학보의 철학 분과를 분석하며 가장 먼저 눈에 띈 것은 <strong>텍스트의 언어적 표현 방식</strong>이었다. 서구 학문의 영향력을 배제하려는 듯 영어를 일절 쓰지 않고 외래어조차 발음 나는 그대로 바꾸거나 번역하여 사용하고 있었다. 흥미로운 점은 이러한 철저한 우리말 표기가 외부의 우려와 달리, 독자 입장에서는 오히려 보기 편하고 글의 흐름을 자연스럽게 만들어 가독성을 높여주었다는 사실이다. 비록 이 과정에서 단어 자체의 본래 의미가 북한 체제에 맞게 변동된 부분들이 발견되기는 했으나, 언어적 이질감을 줄여 텍스트에 쉽게 몰입하게 만드는 묘한 효과가 있었다.</p><p>그러나 자연스러운 문체와 달리 학술지로서의 형식은 대단히 기형적이었다. 일반적인 논문과 달리 참고문헌이 전무했으며, 모든 글이 &quot;경애하는 김정은동지께서는 이렇게 말씀하셨다&quot;로 시작해 지도자의 교시 자체를 유일한 논거로 삼고 있었다. 이번 과제에서는 학보에 수록된 두 편의 핵심 논문을 중심으로 북한 철학의 담론을 살펴보았다.</p><p>첫 번째로 읽은 《교육문제는 절대로 양보할 수 없는 제1의 국사》에서는 체제 유지를 위한 사상 통제의 도구로서 교육을 다루고 있었다. 논문은 과거 사회주의 제도가 붕괴한 국가들의 결정적 원인을 후대 교육의 실패로 규정하며 다음과 같이 강하게 자본주의를 비판했다.</p><blockquote><p>&quot;사상을 기본으로 틀어쥐지 못하고 후대교육을 잘하지 못한 대가로 근로하는 인민대중이 얻은 것은 황금만능과 약육강식의 법칙이 지배하는 비인간적인 자본주의 사회였다&quot;</p></blockquote><p>두 번째 논문인 《주체사상은 자주시대의 영원한 철학사상》에서는 현시대를 과학기술의 격차로 강자와 약자가 나뉘는 시대로 정의하며, 외부의 기술 견제 속에서 스스로 발전해야 한다는 &#39;주체성&#39;을 강조했다. 그 과정에서 은근히 자신들의 우수한 과학 발전 성과를 틈새 어필하는 프로파간다적 치밀함도 보였다.</p><p>이 논문은 주체사상이 세계 수억 명의 마음을 사로잡은 &quot;세계관적 무기&quot;라고 선전하며, 유물론을 기반으로 하되 &#39;세계에서 사람이 차지하는 지위와 역할&#39;을 새로 규정했다고 주장한다. 즉, &quot;사람이 모든 것의 주인이며 모든 것을 결정한다&quot;는 철학적 원리다. 이 거창한 &#39;인간 중심 철학&#39;이 실제 북한 주민들의 서사 속에서는 어떻게 작동하는지 확인하기 위해 특수문헌실에 소장된 문학 작품들을 찾아 읽었다.</p><h2 id="본론-2-문학-소설-분석-—-구조화된-서사-공식과-주체철학의-그림자" tabindex="-1">본론 2: 문학 소설 분석 — 구조화된 서사 공식과 주체철학의 그림자 <a class="header-anchor" href="#본론-2-문학-소설-분석-—-구조화된-서사-공식과-주체철학의-그림자" aria-label="Permalink to &quot;본론 2: 문학 소설 분석 — 구조화된 서사 공식과 주체철학의 그림자&quot;">​</a></h2><p>학보에서 파악한 &#39;인간 중심 담론&#39;과 &#39;사상 교육&#39;의 프레임이 대중문화 속에서 어떻게 발현되는지 확인하기 위해 단편소설집 《소원》(문예출판사, 1992)에 실린 림재성의 소설 〈담력〉과, 1994년 천리마정신을 배경으로 한 <strong>〈뜨락또르운전수 일가〉</strong> 관련 자료를 각각 분석해 보았다. 서로 다른 두 작품이었지만, 놀랍게도 그 내부를 흐르는 서사 공식은 완벽하게 일치하고 있었다.</p><p>두 작품은 모두 겉보기에 대단히 <strong>인본주의적인 외양</strong>을 취한다. 고되고 힘든 노동 현장에서 묵묵히 헌신하고 열심히 살아가는 평범한 주인공과 그 일가의 삶을 조명하며, 주체철학이 말하는 &#39;세계의 주인으로서의 인간&#39;을 묘사하는 듯한 인상을 준다.</p><p>그러나 서사가 전개될수록 철저하게 검열되고 가공된 흔적들이 여실히 드러난다. 가장 도드라지는 특징은 최고 지도자가 언급되거나 등장할 때마다 글이 급격하게 길어지며 찬양조의 수식어로 비대해진다는 점이다. &quot;위대한 수령 김일성 동지 만세&quot;, &quot;위대한 지도자 김정은 동지 만세&quot;와 같은 정치적 슬로건들이 텍스트 곳곳에 배치되어 문학의 순수성을 압도한다.</p><p>결정적으로 두 소설 속 주인공들의 고난과 갈등이 해결되는 방식은 주체철학의 모순을 그대로 폭로한다. 주인공들이 아무리 주체적으로 치열하게 살아 가도, 결국 문제의 최종 해결은 &#39;지도자가 나타나 그 노동을 인정해 주고 뜨락또르(트랙터)를 선물해 주는&#39; 시혜적 사건을 통해 이루어진다. 지도자는 늘 국가를 위해 바쁘게 정치를 펼치는 유일한 능동적 &#39;주체&#39;로 묘사되고, 인민은 그가 베푸는 상과 인정에 감격하며 &quot;이때까지 일궈온 과업에 그치지 말고 더 열심히 노동하라&quot;는 교시를 받아드는 수동적인 &#39;객체&#39;에 머문다.</p><h2 id="결론-철학적-렌즈로-바라본-북한-자료의-총평" tabindex="-1">결론: 철학적 렌즈로 바라본 북한 자료의 총평 <a class="header-anchor" href="#결론-철학적-렌즈로-바라본-북한-자료의-총평" aria-label="Permalink to &quot;결론: 철학적 렌즈로 바라본 북한 자료의 총평&quot;">​</a></h2><p>이번 특수문헌실 과제를 통해 접한 북한의 철학 학보와 문학 자료들은, 철저히 통제된 사회가 어떻게 학문과 문화를 유기적으로 가공하여 체제를 유지하는지 보여주는 생생한 증거였다.</p><p>외래어를 배제하고 우리말로 풀어쓴 문체는 독자에게 높은 가독성과 자연스러움을 선사하는 긍정적인 면이 있었지만, 그 친숙한 언어의 장막 뒤에는 단어의 의미를 이념적으로 변동시키고 사상을 주입하려는 치밀한 계산이 깔려 있었다. 학보가 참고문헌도 없이 최고 지도자의 교시를 절대적 원리로 정립하는 &#39;이론적 가이드라인&#39;이었다면, 소설들은 그 이론이 인민의 일상과 감정을 지배하도록 정서적으로 침투하는 &#39;실천적 도구&#39;였던 것이다.</p><p>결과적으로 주체사상이 주장하는 &quot;사람이 모든 것의 주인&quot;이라는 철학적 명제는 심각한 내적 모순을 안고 있다. 소설 속에서 증명되듯 모든 것을 결정하고 시혜를 베푸는 진정한 &#39;주인&#39;은 오직 최고 지도자 한 사람뿐이며, 근로하는 인민대중은 그 결정에 감격하며 끊임없이 희생과 노동을 바쳐야 하는 존재로 귀결되기 때문이다. 철학 전공자로서 텍스트의 언어적 특징과 담론 구조를 선제적으로 파악하고 접근했기에, 북한 자료가 가진 겉면의 자연스러움과 인본주의적 가면 뒤에 숨은 정치적 실상을 보다 비판적이고 입체적으로 읽어낼 수 있었던 뜻깊은 경험이었다.</p>',19)])])}const c=t(r,[["render",_]]);export{h as __pageData,c as default};
